/*------------------Progress Bars-------------------*/
.progressbar {
  display: block;
  position: absolute;
  width: 20px;
  height: 320px;
  box-sizing: border-box;
  border: 1px #777 solid;
  background: rgba(0, 0, 0, 0.55);
  top: 0;
  border-radius: 3px;
  overflow: hidden;
  /* Two glass tubes inside the shared wrapper */
}
.progressbar::before,
.progressbar::after {
  content: '';
  position: absolute;
  top: 1px;
  bottom: 1px;
  width: 7px;
  border-radius: 2px;
  pointer-events: none;
  z-index: 4;
  mix-blend-mode: screen;
  background-image: linear-gradient(90deg, rgba(255, 255, 255, 0.24) 0%, rgba(255, 255, 255, 0.1) 16%, rgba(255, 255, 255, 0) 42%, rgba(0, 0, 0, 0.1) 72%, rgba(255, 255, 255, 0.12) 100%), linear-gradient(104deg, transparent 0%, rgba(255, 255, 255, 0.32) 24%, rgba(255, 255, 255, 0.06) 42%, transparent 60%), linear-gradient(180deg, rgba(255, 255, 255, 0.08) 0%, rgba(255, 255, 255, 0) 30%, rgba(255, 255, 255, 0) 70%, rgba(255, 255, 255, 0.06) 100%);
  background-size: 100% 100%, 220% 100%, 100% 100%;
  background-repeat: no-repeat;
  background-position: 0 0, 120% 0, 0 0;
  opacity: 0.82;
  animation: tubeSpecularDrift 7.4s ease-in-out infinite alternate;
}
.progressbar::before {
  left: 1px;
}
.progressbar::after {
  left: 10px;
  animation-direction: alternate-reverse;
  animation-delay: -1.6s;
}
#leftpanel .progressbar {
  z-index: 3;
}
#rightpanel .progressbar {
  position: relative;
  right: 0;
  top: auto;
  bottom: auto;
}
.progressbar .bar {
  --progress-fill-width: 7px;
  display: block;
  position: absolute;
  width: 18px;
  height: 0;
  bottom: 0;
  background: none;
  border-radius: 2px;
}
.bar .previewbar {
  display: block;
  position: absolute;
  left: 0;
  width: var(--progress-fill-width);
  height: 0;
  background: rgba(0, 0, 0, 0.75);
  z-index: 1;
  border-radius: 2px;
  transition: background-color 180ms linear, box-shadow 180ms linear;
  will-change: background-color, background-image, box-shadow;
}
.bar .previewbar.glow-active {
  filter: drop-shadow(0 0 3px rgba(255, 255, 255, 0.4)) drop-shadow(0 0 2px currentColor);
}
.bar .currentbar {
  display: block;
  position: absolute;
  left: 0;
  width: var(--progress-fill-width);
  height: 0;
  bottom: 0;
  border-radius: 2px;
  background: rgba(0, 0, 0, 0.75);
  overflow: hidden;
  opacity: 1;
  animation: none;
  will-change: height, background-color, background-image;
}
.bar .currentbar::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: linear-gradient(180deg, rgba(255, 255, 255, 0.24) 0%, rgba(255, 255, 255, 0.06) 30%, rgba(255, 255, 255, 0.02) 56%, rgba(0, 0, 0, 0.14) 100%);
  background-size: 100% 120%;
  pointer-events: none;
  opacity: 0.24;
  animation: barSheenSweep 3.2s ease-in-out infinite alternate;
}
.bar .currentbar::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle, rgba(255, 255, 255, 0.38) 0 2px, rgba(255, 255, 255, 0) 2.2px), radial-gradient(circle, rgba(255, 255, 255, 0.26) 0 1.5px, rgba(255, 255, 255, 0) 1.7px), radial-gradient(circle, rgba(0, 0, 0, 0.2) 0 1.3px, rgba(0, 0, 0, 0) 1.5px);
  background-size: 16px 34px, 13px 42px, 17px 48px;
  background-repeat: repeat;
  pointer-events: none;
  opacity: 0.68;
  animation: barTextureDrift 1.6s linear infinite;
}
.bar .currentbar:not(.no-glow) {
  filter: drop-shadow(0 0 3px rgba(255, 255, 255, 0.4)) drop-shadow(0 0 2px currentColor);
}
.bar .currentbar.no-glow {
  animation: none;
  opacity: 1;
  filter: none;
}
.bar .currentbar.no-glow::before {
  animation: none;
  opacity: 0;
}
.bar .currentbar.no-glow::after {
  animation: none;
  opacity: 0;
}
